import json, glob, os, sys, re
from datetime import datetime
d = sys.argv[1]
def p(s): return datetime.fromisoformat(s.replace('Z','+00:00'))
for f in sorted(glob.glob(os.path.join(d, 'agent-*.jsonl')), key=lambda f: open(f).readline()):
    meta = json.load(open(f[:-6] + '.meta.json')); label = meta.get('description')
    calls = []; t0 = None; results = {}
    for line in open(f, errors='replace'):
        try: r = json.loads(line)
        except Exception: continue
        t = r.get('timestamp'); t0 = t0 or t
        m = r.get('message')
        if not isinstance(m, dict): continue
        c = m.get('content')
        if not isinstance(c, list): continue
        for b in c:
            if b.get('type') == 'tool_use':
                calls.append((t, m.get('id'), b.get('id'), b.get('name'), json.dumps(b.get('input'))))
            if b.get('type') == 'tool_result':
                txt = b.get('content')
                if isinstance(txt, list): txt = ' '.join(x.get('text','') for x in txt if isinstance(x, dict))
                results[b.get('tool_use_id')] = (b.get('is_error'), str(txt)[:300])
    # first message id's calls
    first_mid = calls[0][1] if calls else None
    first_turn = [c[3] + ':' + c[4][:80] for c in calls if c[1] == first_mid]
    brief_idx = None
    for i, c in enumerate(calls):
        if c[3] == 'Bash' and 'facts-extract.sh' in c[4]:
            brief_idx = i; break
    print(f"== {label} {os.path.basename(f)[6:14]} calls={len(calls)} start={t0}")
    print("  first turn:", first_turn)
    if brief_idx is not None:
        c = calls[brief_idx]
        print(f"  first facts-extract at call {brief_idx+1}, {(p(c[0])-p(t0)).total_seconds():.0f}s after start: {c[4][:200]}")
    errs = [(c[3], results.get(c[2], (None,''))[1][:160]) for c in calls if results.get(c[2], (None,))[0]]
    print(f"  errors: {len(errs)}")
    for e in errs: print('    ', e)
    for c in calls:
        if c[3] == 'Bash' and re.search(r'ant (compileAll|clean|testQuick|testSystem|testSpecData|testFast)|checker-count/run.sh|distance/run.sh|sleep ', c[4]):
            print('   run', c[0][11:19], c[4][:170])
EOF
